import { buildChannels, buildChecks, buildComponents, buildStatusPages } from "./build.js";
import { renderVariableBlock } from "./hcl.js";
/** Pinned the same way the provider's own `examples/provider/provider.tf`
 * pins it -- see `packages/terraform-provider-realuptime/examples/provider/provider.tf`
 * and `docs/index.md`. Update both places together if the provider cuts a
 * breaking (0.2+) release. */
const PROVIDER_VERSION_CONSTRAINT = "~> 0.1";
function header(comment) {
    return `# ${comment}\n# Generated by \`realuptime terraform export\` (REA-533). Review before applying.\n`;
}
function tfvarsExample(variables) {
    if (variables.length === 0)
        return "";
    const lines = [
        "# realuptime terraform export (REA-533): notification channel credentials.",
        "# The REST API never returns a channel's webhook URL or API key (write-only",
        "# by design), so these could not be filled in automatically. Copy this file",
        "# to terraform.tfvars, fill in the real values from wherever the credential",
        "# was originally issued, and keep terraform.tfvars out of version control.",
        "",
    ];
    for (const variable of variables) {
        lines.push(`# ${variable.description}`);
        lines.push(`${variable.name} = "REPLACE_ME"`);
        lines.push("");
    }
    return `${lines.join("\n").trimEnd()}\n`;
}
/**
 * Builds every generated file and the matching `terraform import` commands
 * from the account's checks/status pages/components/channels (REA-533).
 * Writing files to disk is the caller's job (`commands/terraform.ts`) so
 * this stays pure and unit-testable.
 */
export function buildTerraformExport(input) {
    const { checks: builtChecks, skipped: skippedChecks } = buildChecks(input.checks);
    const builtStatusPages = buildStatusPages(input.statusPages);
    const statusPageAddressById = new Map(input.statusPages.map((page, index) => [page.id, builtStatusPages[index].address]));
    const checkAddressById = new Map(builtChecks.map((c) => [c.id, c.address]));
    const allComponents = [];
    for (const page of input.statusPages) {
        allComponents.push(...(input.componentsByStatusPageId.get(page.id) ?? []));
    }
    const builtComponents = buildComponents(allComponents, statusPageAddressById, checkAddressById);
    const { channels: builtChannels, variables, skipped: skippedChannels } = buildChannels(input.channels);
    const files = [];
    files.push({
        path: "provider.tf",
        content: `${header("Provider configuration for the RealUptime Terraform provider.")}terraform {
  required_providers {
    realuptime = {
      source  = "RealUptimeHQ/realuptime"
      # Pinned to the same minor-version range the provider's own docs use;
      # widen deliberately, not by dropping this constraint.
      version = "${PROVIDER_VERSION_CONSTRAINT}"
    }
  }
}

# The key comes from REALUPTIME_API_KEY; set api_key here only from a secret
# store, never a literal. base_url is optional (REALUPTIME_API_URL also works).
provider "realuptime" {}
`,
    });
    if (builtChecks.length > 0) {
        files.push({ path: "checks.tf", content: `${header(`${builtChecks.length} http check${builtChecks.length === 1 ? "" : "s"}.`)}\n${builtChecks.map((c) => c.block).join("\n\n")}\n` });
    }
    if (builtStatusPages.length > 0) {
        files.push({
            path: "status_pages.tf",
            content: `${header(`${builtStatusPages.length} status page${builtStatusPages.length === 1 ? "" : "s"}.`)}\n${builtStatusPages.map((p) => p.block).join("\n\n")}\n`,
        });
    }
    if (builtComponents.length > 0) {
        files.push({
            path: "status_page_components.tf",
            content: `${header(`${builtComponents.length} status page component${builtComponents.length === 1 ? "" : "s"}.`)}\n${builtComponents.map((c) => c.block).join("\n\n")}\n`,
        });
    }
    if (builtChannels.length > 0) {
        const variableBlocks = variables.map((v) => renderVariableBlock(v.name, { sensitive: v.sensitive, description: v.description }));
        files.push({
            path: "notification_channels.tf",
            content: `${header(`${builtChannels.length} notification channel${builtChannels.length === 1 ? "" : "s"}. Credentials are variables -- see terraform.tfvars.example.`)}\n${[...builtChannels.map((c) => c.block), ...variableBlocks].join("\n\n")}\n`,
        });
    }
    const tfvars = tfvarsExample(variables);
    if (tfvars)
        files.push({ path: "terraform.tfvars.example", content: tfvars });
    const importCommands = [
        ...builtChecks.map((c) => `terraform import realuptime_check.${c.address} ${c.importId}`),
        ...builtStatusPages.map((p) => `terraform import realuptime_status_page.${p.address} ${p.importId}`),
        ...builtComponents.map((c) => `terraform import realuptime_status_page_component.${c.address} ${c.importId}`),
        ...builtChannels.map((c) => `terraform import realuptime_notification_channel.${c.address} ${c.importId}`),
    ];
    if (importCommands.length > 0) {
        files.push({
            path: "import.sh",
            content: `#!/bin/sh
# realuptime terraform export (REA-533): brings the account's existing
# resources under Terraform management without recreating them. The
# RealUptime provider's resources import by \`terraform import\`, not import
# blocks (see packages/terraform-provider-realuptime/examples/**/import.sh) --
# run this once, after \`terraform init\`, before the first \`terraform plan\`.
# A notification channel's config is write-only server-side, so its first
# plan after import still shows one in-place update once terraform.tfvars is filled in.
set -eu

${importCommands.join("\n")}
`,
        });
    }
    return {
        files,
        importCommands,
        counts: { checks: builtChecks.length, statusPages: builtStatusPages.length, components: builtComponents.length, channels: builtChannels.length },
        skipped: [...skippedChecks, ...skippedChannels],
    };
}
